import React, { useState, useEffect } from "react";
import { Link } from "react-router-dom";
import axios from "axios";

const Funds = () => {
  // 1. Database se balance store karne ke liye state
  const [availableMargin, setAvailableMargin] = useState(0);

  // 2. Page load hote hi current balance fetch karna
  useEffect(() => {
    const fetchFunds = async () => {
      try {
        const res = await axios.get("http://localhost:8080/userFunds");
        setAvailableMargin(res.data.margin || 0); // Backend data state mein save
      } catch (err) {
        console.error("Error fetching funds:", err);
      }
    };
    fetchFunds();
  }, []);

  // 3. Add Funds Function (Positive amount bhejta hai)
  const handleAddFunds = async () => {
    const amount = prompt("Kitna paisa add karna chahte hain?");
    if (amount && !isNaN(amount)) {
      try {
        await axios.post("http://localhost:8080/addFunds", { 
          amount: Number(amount) 
        });
        alert(`₹${amount} safaltapurvak add ho gaye!`);
        window.location.reload(); // UI refresh naya balance dekhne ke liye
      } catch (err) {
        alert("Paisa add nahi ho paya!");
      }
    }
  };

  // 4. Withdraw Function (Negative amount bhejta hai)
  const handleWithdraw = async () => {
    const amount = prompt("Kitna paisa nikalna (Withdraw) chahte hain?");
    if (amount && !isNaN(amount)) {
      const withdrawValue = Number(amount);
      if (withdrawValue > availableMargin) {
        alert("Aapke paas itna balance nahi hai!");
        return;
      }
      try {
        // Backend ki /addFunds API hi use hogi, bas amount minus mein jayega
        await axios.post("http://localhost:8080/addFunds", { 
          amount: -withdrawValue 
        });
        alert(`₹${withdrawValue} withdraw ho gaye!`);
        window.location.reload(); 
      } catch (err) {
        alert("Withdrawal fail ho gaya!");
      }
    }
  };

  return (
    <>
      <div className="funds">
        <p>Instant, zero-cost fund transfers with UPI</p>

        {/* Buttons par click karne se functions trigger honge */}
        <button className="btn btn-green" onClick={handleAddFunds} style={{cursor: "pointer", border: "none"}}>
          Add funds
        </button>
        <button className="btn btn-blue" onClick={handleWithdraw} style={{cursor: "pointer", border: "none"}}>
          Withdraw
        </button>
      </div>

      <div className="row">
        <div className="col">
          <span>
            <p>Equity</p>
          </span>

          <div className="table">
            <div className="data">
              <p>Available margin</p>
              {/* Database wala dynamic balance */}
              <p className="imp colored">{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            <div className="data">
              <p>Used margin</p>
              <p className="imp">0.00</p>
            </div>
            <div className="data">
              <p>Available cash</p>
              <p className="imp">{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            <hr />
            <div className="data">
              <p>Opening Balance</p>
              <p>{availableMargin.toLocaleString(undefined, { minimumFractionDigits: 2 })}</p>
            </div>
            {/* Baaki static rows ko waise hi rakha hai */}
            <div className="data">
              <p>Payin</p>
              <p>0.00</p>
            </div>
            <div className="data">
              <p>SPAN</p>
              <p>0.00</p>
            </div>
          </div>
        </div>

        <div className="col">
          <div className="commodity">
            <p>You don't have a commodity account</p>
            <Link className="btn btn-blue">Open Account</Link>
          </div>
        </div>
      </div>
    </>
  );
};

export default Funds;
